sys_variable_value.value:
(function execute(inputs, outputs) {
 // ---- adjust to your instance ----
    var ESCROW    = 'x_2210852_odee_s_0_odee_ticket';
    var CLIENT_ID = 'SERVICENOW';
    var P_MARK    = 'x_2210852_odee_s_0.poll_watermark';
    // var EVT_STATUS   = 'x_2210852_odee_s_0.opendata.status_changed';
    // var EVT_ASSIGNEE = 'x_2210852_odee_s_0.opendata.assignee_changed';

    var OVERLAP_SECONDS = 60;    // re-read a little; the guard discards duplicates
    var FIRST_RUN_SECONDS = 900;

    var SYNCED = 'synced', CONFLICT = 'conflict';

    var map = new OD_Map();
    var api = new OD_Auth();

    var processed = 0, changed = 0, errors = 0;

    // ---------- 1. the window ----------
    var to   = new GlideDateTime();
    var mark = gs.getProperty(P_MARK, '');
    var from = new GlideDateTime();
    if (mark) { from.setValue(mark); } else { from.addSeconds(-FIRST_RUN_SECONDS); }
    from.addSeconds(-OVERLAP_SECONDS);

    var fromStr = utc(from), toStr = utc(to);
    outputs.window = fromStr + ' .. ' + toStr;

    // ---------- 2. fetch ----------
    var rows = [];
    try {
        var path = '/ticket?hasExternalTicketId=true'
                 + '&clientId='     + encodeURIComponent(CLIENT_ID)
                 + '&modifiedFrom=' + encodeURIComponent(fromStr)
                 + '&modifiedTo='   + encodeURIComponent(toStr);
        var res = api.call('GET', path, null);
        rows = (res && res.data) ? res.data : [];
    } catch (e) {
        outputs.processed = 0; outputs.changed = 0; outputs.errors = 1;
        gs.error('[odee poll] fetch failed, watermark NOT advanced: ' + e);
        return;                       // leave the watermark where it was
    }

    const status_map_snow_odee = {
        1: 'new',
        2: 'in_progress',
        3: 'on_hold',
        6: 'resolved',
        7: 'closed',
        8: 'canceled'
    };

    const status_map_odee_snow = {
        'new': 1,
        'in_progress': 2,
        'on_hold': 3,
        'resolved': 6,
        'closed': 7,
        'canceled': 8
    };

    // ---------- 3. reconcile ----------
    for (var i = 0; i < rows.length; i++) {
        var t = rows[i];
        processed++;
        try {
            var g = new GlideRecord(ESCROW);
            g.addQuery('u_external_ticket_id', String(t.externalTicketId));
            g.setLimit(1);
            g.query();
            if (!g.next()) {
                gs.warn('[odee poll] no escrow record for ' + t.externalTicketId);
                continue;
            }

            // RAW to RAW. Comparing the mapped state here would hide 100 -> 110.
            var oldStatus   = parseInt(g.u_od_status_id, 10);
            var newStatus   = parseInt(t.statusId, 10);
            var oldAssignee = String(g.u_od_assignee || '');
            var newAssignee = String(t.assigneeName || '');

            var statusMoved   = !isNaN(newStatus) && newStatus !== oldStatus;
            var assigneeMoved = newAssignee !== oldAssignee;

            if (!statusMoved && !assigneeMoved) continue;   // echo, or overlap duplicate

            var inc = new GlideRecord('incident');
            var haveInc = inc.get(g.getValue('u_incident'));
            var incClosed = haveInc && (inc.state == 7 || inc.state == 8);

            // Never reopen a closed incident from a poll. Park it instead.
            var conflict = statusMoved && incClosed && !map.isTerminal(newStatus);

            // ---- 3a. ESCROW FIRST. Ordering is load-bearing: Flow 2's guard
            //      reads u_od_state, so it must be current before we touch Incident.
            if (!g.correlation_id && t.internalTicketId) {
                g.correlation_id      = String(t.internalTicketId);   // free backfill
                g.correlation_display = 'Modius OpenData';
            }
            g.u_od_status_id   = newStatus;
            g.u_od_state       = status_map_snow_odee[map.statusIdToState(newStatus)];
            g.u_od_assignee    = newAssignee;
            if (t.urgencyLevelId != null) g.u_od_urgency_id = t.urgencyLevelId;
            if (t.modificationDate) g.u_od_modified = fromDTZ(t.modificationDate);
            g.u_direction  = 'inbound';
            g.u_sync_state = conflict ? CONFLICT : SYNCED;
            g.active       = !(map.isTerminal(newStatus) && !conflict);
            g.update();

            // ---- 3b. then the Incident ----
            if (haveInc && statusMoved && !conflict) {                
                inc.state = map.statusIdToState(newStatus);
                inc.work_notes = 'OpenData status: ' + (t.statusName || newStatus);

                if (map.statusIdToState(newStatus) === 6) {
                        inc.close_code  = "OpenData - Resolved";
                        inc.close_notes = 'Resolution: ' + (t.statusName || newStatus);
                } else if (map.statusIdToState(newStatus) === 7) {
                        inc.close_code  = "OpenData - Closed";
                        inc.close_notes = 'Resolution: ' + (t.statusName || newStatus);
                }
                inc.update();
            }

            // ---- 3c. fan out ----
            // if (statusMoved)   gs.eventQueue(EVT_STATUS,   g, String(oldStatus),  String(newStatus));
            // if (assigneeMoved) gs.eventQueue(EVT_ASSIGNEE, g, oldAssignee, newAssignee);
            changed++;

        } catch (e) {
            errors++;
            gs.error('[odee poll] ' + t.externalTicketId + ': ' + e);
        }
    }

    // ---------- 4. advance ONLY on a clean run ----------
    if (errors === 0) {
        gs.setProperty(P_MARK, to.getValue());
    } else {
        gs.error('[odee poll] ' + errors + ' error(s); watermark held at ' + (mark || 'unset'));
    }

    outputs.processed = processed;
    outputs.changed   = changed;
    outputs.errors    = errors;

    // ---------------------------------------------------------------

    // OpenData accepts Z as an offset, and Z needs no URL-encoding —
    // which sidesteps the '+' becoming a space in a query string.
    function utc(gdt) {
        return gdt.getValue().replace(' ', 'T') + 'Z';
    }

    // Responses come back in the offset we asked for, i.e. Z, so stripping
    // it yields the UTC value GlideDateTime expects.
    function fromDTZ(v) {
        var s = String(v).replace('T', ' ').replace(/(Z|[+-]\d{2}:\d{2})$/, '');
        return new GlideDateTime(s);
    }
})(inputs, outputs);

